# Regenerates the C++ port's generated files from the C# library's assets:
#   cpp/BlazeImGui/blaze_icons.h       ICON_LC_* UTF-8 macros, from src/BlazeImGui/Icons.g.cs
#   cpp/BlazeImGui/blaze_font_data.cpp Inter + Lucide embedded as arrays, from src/BlazeImGui/Assets/Fonts
# Usage: powershell -File tools/generate-cpp.ps1   (run generate-icons.ps1 first when updating Lucide)
$ErrorActionPreference = "Stop"
$root = Split-Path $PSScriptRoot
$fonts = Join-Path $root "src\BlazeImGui\Assets\Fonts"
$out = Join-Path $root "cpp\BlazeImGui"

# ---------------------------------------------------------------- icons
$cs = Get-Content (Join-Path $root "src\BlazeImGui\Icons.g.cs") -Raw
$range = [regex]::Match($cs, 'RangeStart = 0x([0-9A-F]+), RangeEnd = 0x([0-9A-F]+)')
$icons = [regex]::Matches($cs, 'public const string (\w+) = "\\u([0-9A-F]{4})";')

function Utf8([int]$cp) {
    $b = @((0xE0 -bor ($cp -shr 12)), (0x80 -bor (($cp -shr 6) -band 0x3F)), (0x80 -bor ($cp -band 0x3F)))
    return ($b | ForEach-Object { '\x{0:X2}' -f $_ }) -join ''
}

$sb = [Text.StringBuilder]::new()
[void]$sb.AppendLine('// <auto-generated> Lucide icon font codepoints as UTF-8 string literals (ISC license).')
[void]$sb.AppendLine('// Browse icons at https://lucide.dev/icons - "chevron-right" -> ICON_LC_CHEVRON_RIGHT.')
[void]$sb.AppendLine('// Literals concatenate: Blaze::Ui::Button(ICON_LC_SAVE "  Save").')
[void]$sb.AppendLine('// Regenerate with tools/generate-cpp.ps1; do not edit by hand.')
[void]$sb.AppendLine('#pragma once'); [void]$sb.AppendLine('')
[void]$sb.AppendLine(('#define ICON_MIN_LC 0x{0}' -f $range.Groups[1].Value))
[void]$sb.AppendLine(('#define ICON_MAX_LC 0x{0}' -f $range.Groups[2].Value)); [void]$sb.AppendLine('')
$seen = @{}
foreach ($m in $icons) {
    # PascalCase -> UPPER_SNAKE: a break before each capital and between letters and digits.
    $name = $m.Groups[1].Value.TrimStart('_')
    $snake = [regex]::Replace($name, '(?<=[a-z0-9])(?=[A-Z])|(?<=[A-Z])(?=[A-Z][a-z])|(?<=[A-Za-z])(?=[0-9])', '_').ToUpper()
    $macro = "ICON_LC_$snake"
    if ($seen.ContainsKey($macro)) { continue }
    $seen[$macro] = 1
    [void]$sb.AppendLine(('#define {0} "{1}"' -f $macro, (Utf8 ([Convert]::ToInt32($m.Groups[2].Value, 16)))))
}
[IO.File]::WriteAllText((Join-Path $out "blaze_icons.h"), $sb.ToString())
"Wrote $($seen.Count) icons"

# ---------------------------------------------------------------- fonts
$files = [ordered]@{
    InterRegular = "Inter-Regular.ttf"; InterMedium = "Inter-Medium.ttf"; InterSemiBold = "Inter-SemiBold.ttf"
    InterBold = "Inter-Bold.ttf"; Lucide = "lucide.ttf"
}
$sb = [Text.StringBuilder]::new()
[void]$sb.AppendLine('// <auto-generated> Inter (SIL OFL 1.1) and Lucide (ISC) embedded for blaze_imgui.cpp.')
[void]$sb.AppendLine('// Licenses: fonts/Inter-LICENSE.txt, fonts/Lucide-LICENSE.txt. Regenerate with tools/generate-cpp.ps1.')
[void]$sb.AppendLine('#include "blaze_font_data.h"'); [void]$sb.AppendLine('')
[void]$sb.AppendLine('namespace Blaze::FontData'); [void]$sb.AppendLine('{')
foreach ($key in $files.Keys) {
    $bytes = [IO.File]::ReadAllBytes((Join-Path $fonts $files[$key]))
    $padded = New-Object byte[] ([Math]::Ceiling($bytes.Length / 4) * 4)
    [Array]::Copy($bytes, $padded, $bytes.Length)
    [void]$sb.AppendLine("    // $($files[$key])")
    [void]$sb.AppendLine("    const unsigned int ${key}Size = $($bytes.Length);")
    [void]$sb.Append("    alignas(4) const unsigned int ${key}[] = {")
    for ($i = 0; $i -lt $padded.Length; $i += 4) {
        if (($i / 4) % 16 -eq 0) { [void]$sb.Append("`n        ") }
        [void]$sb.Append(('0x{0:X8},' -f [BitConverter]::ToUInt32($padded, $i)))
    }
    [void]$sb.AppendLine("`n    };"); [void]$sb.AppendLine('')
}
[void]$sb.AppendLine('}')
[IO.File]::WriteAllText((Join-Path $out "blaze_font_data.cpp"), $sb.ToString())
"Wrote $($files.Count) fonts"
